    import importlib
    dirname = parser_dict.get('dirname')
    if dirname is None:
        raise ValueError("dirname is missing in include directive")
    if not ut.ensurepath(dirname):
        raise ValueError("invalid dirname in include directive")
    if not ut.isdir(dirname):
        raise ValueError("dirname in include directive must be a directory")
    files = set(ut.splitpath(dirname))
    for file in files:
        module = importlib.import_module('.'.join(['.'.join([self.domain, self.name]), ut.splitext(file)[0]]))
        if not hasattr(module, '__all__'):
            continue
        for name in module.__all__:
            if not name.startswith(self.name):
                raise ValueError("only names starting with '{}' are allowed in include directive".format(self.name))
            self.add_parser_object(getattr(module, name), file)

def get_deprecated_args(self):
    """Returning dict with options which deprecate others. """
    return {}

def get_deprecated_options(self):
    """Returning dict with options which deprecate others. """
    return {self.get_deprecated_args()}

def get_deprecated_options(self):
    """Returning dict with options which deprecate others. """
    return {self.get_deprecated_options(): {self.get_deprecated_options(): {}

def get_option_spec(self, command_name, argument_name):
    """Gets the specification for the specified option name. """
    if command_name not in self._option_specs:
        raise ValueError("Unknown command name: {}".format(command_name))

    if argument_name not in self._option_specs[command_name]:
        raise ValueError("Unknown argument name: {}".format(argument_name))

    return self._option_specs[command_name][argument_name]

def validate_length_args(self, args):
    """
    Check if value of arguments is not longer than length specified.

    :param args: The received arguments.
    """
    for param in args:
        try:
            length = len(param.value)
            if length > param.length:
                raise ValueError("Length of value must be less than {}".format(param.length))
        except:
            print("Invalid input for parameter '{}'.".format(param.name))

    return args

def validate_choices_args(self, *args):
    """Check if value of choice arguments is one of the available choices.

    :param args: The received arguments.
    """
    # check if we have any arguments
    if not args:
        # if not, raise an error
        raise ValueError("No arguments provided")

    # loop over the received arguments
    for arg in args:
        # check if the argument is a choice argument
        if "choices" in arg:
            # if it is, loop over the available choices
            for choice in arg["choices"]:
                # check if the argument value is one of the available choices
                if arg["value"] == choice:
                    # if it is, continue to the next argument
                    break
            else:
                # if it is not, raise an error
                raise ValueError(f"Invalid choice {arg['value']} for argument {arg['name']}")

    # continue to the next argument
    continue

def get_nested_custom_and_control_args(self, args):
    control_args = {}
    nested_args = {}
    custom_args = {}
    for name, value in args.items():
        if name.startswith("-CONTROL"):
            control_args[name] = value
        elif name.startswith("-CUSTOM"):
            custom_args[name] = value
        else:
            nested_args[name] = value
    return (control_args, nested_args, custom_args)

def merge_extra_vars(vars_dict, extra_vars=None):
    """Extend ``vars_dict`` with ``extra_vars``

    :param vars_dict: Dictionary to merge extra-vars into
    :param extra_vars: List of extra-vars
    """
    if extra_vars is None:
        return vars_dict

    if not isinstance(extra_vars, list):
        raise TypeError("'extra_vars' must be a list, got {}".format(type(extra_vars)))

    for extra_var in extra_vars:
        var_name = extra_var["name"]
        if var_name not in vars_dict:
            vars_dict[var_name] = extra_var["value"]

    return vars_dict

def _convert_non_cli_args(self, parser_name, values_dict):
    """Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of with arguments
    """

    parser = self.known_commands[parser_name]
    for opt in parser.options:
        if opt.name in values_dict:
            values_dict[opt.name] = opt.convert(values_dict[opt.name])
        # Special case for root command if --blotter was not provided
        if parser_name == "main" and opt.name == "blotter" and not values_dict.get(
            "blotter"
        ):
            values_dict[opt.name] = ""

    return values_dict

def inject_config(self):
    if not os.environ.get('CONFIG_PATH'):
        return

    config_path = os.environ['CONFIG_PATH']

    if not os.path.isfile(config_path):
        raise ValueError('Config file does not exist')

    config = ConfigParser.SafeConfigParser()
    config.read(config_path)

    for option in config.options():
        os.environ[option] = config.get(option)

def strip_root(path, root):
    """Remove root from path, throw exception on failure."""
    if not path.startswith(root):
        raise ValueError("Path does not start with root")
    return path[len(root):]
